    (ts) => JSON.stringify(ts.map((t) => ({ id: t.id, url: String(t.url || '').slice(0, 60), active: t.active })))
  ).catch((e) => JSON.stringify([{ err: String(e && e.message || e) }]))`, true) ?? '[]')
